def open_root(path):
    try:
        before=path.lstat()
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
            return None
        fd=os.open(path,os.O_RDONLY|os.O_CLOEXEC|os.O_DIRECTORY|os.O_NOFOLLOW)
        after=os.fstat(fd)
        if (before.st_dev,before.st_ino)!=(after.st_dev,after.st_ino):
            os.close(fd)
            return None
        return fd
    except OSError:
        return None
def open_relative(root_fd,parts,kind):
    fd=os.dup(root_fd)
    try:
        for index,part in enumerate(parts):
            flags=os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW
            if index<len(parts)-1:
                flags|=os.O_DIRECTORY
            next_fd=os.open(part,flags,dir_fd=fd)
            os.close(fd)
            fd=next_fd
        mode=os.fstat(fd).st_mode
        valid=stat.S_ISREG(mode) if kind=="file" else stat.S_ISREG(mode) or stat.S_ISDIR(mode)
        if not valid:
            raise OSError("wrong runtime component type")
        return fd
    except BaseException:
        os.close(fd)
        raise
def runtime(path):
