    if root_fd is None:
        return None
    opened=[]
    try:
        git_fd=open_relative(root_fd,(".git",),"either")
        opened.append(git_fd)
        runner_fd=open_relative(root_fd,("scripts","writer-lease-hook-runner.py"),"file")
        hook_fd=open_relative(root_fd,("python","src","dotfiles_setup","codex_writer_lease_hook.py"),"file")
        opened.append(hook_fd)
    except OSError:
        for fd in opened:
            os.close(fd)
        os.close(root_fd)
        return None
    for fd in opened:
        os.close(fd)
    os.close(root_fd)
    return runner_fd
p=pathlib.Path.cwd().resolve()
roots=[]
for candidate in (p,*p.parents):
    runner_fd=runtime(candidate)
    if runner_fd is not None:
        roots.append((candidate,runner_fd))
if len(roots)!=1:
    for candidate,runner_fd in roots:
        os.close(runner_fd)
    message="Writer lease tracked runtime is ambiguous." if roots else "Writer lease tracked runtime is unavailable."
    sys.stderr.write(message+chr(10))
    raise SystemExit(2)
root,runner_fd=roots[0]
filename=str(root/"scripts"/"writer-lease-hook-runner.py")
